```javascript
import { Group, Mesh, PlaneGeometry } from 'three/webgpu';
import { MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, uniform } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const root = new Group();
  root.position.set(0, 0, 0);
  root.rotation.order = 'YXZ';

  // ============================================================================
  // DESIGN TOKENS
  // ============================================================================
  const TILE_WIDTH = 1.0;
  const TILE_HEIGHT = 0.62;
  const GRID_GAP = 0.25;
  const GRID_COLS = 3;
  const GRID_ROWS = 2;
  const TOTAL_GRID_WIDTH = GRID_COLS * TILE_WIDTH + (GRID_COLS - 1) * GRID_GAP;
  const TOTAL_GRID_HEIGHT = GRID_ROWS * TILE_HEIGHT + (GRID_ROWS - 1) * GRID_GAP;
  const KICKER_OFFSET_Y = 0.3;

  const colorPaper = 0xe8ecf2;

  const brandMarks = [
    'HODINKEE',
    'MONOCLE',
    'WALLPAPER',
    'ESQUIRE',
    'WIRED',
    'FINANCIAL TIMES',
  ];

  // ============================================================================
  // BUILD BACKDROP GRADIENT PLANE
  // ============================================================================
  const backdropGeometry = new PlaneGeometry(8, 6);
  const backdropMaterial = new MeshStandardNodeMaterial();

  const backdropUV = uv();
  const gradTopVec = vec3(26 / 255, 26 / 255, 34 / 255);
  const gradBotVec = vec3(18 / 255, 18 / 255, 24 / 255);
  backdropMaterial.colorNode = mix(gradTopVec, gradBotVec, backdropUV.y);
  backdropMaterial.metalness = uniform(0);
  backdropMaterial.roughness = uniform(1);
  backdropMaterial.emissiveIntensity = 0;

  const backdrop = new Mesh(backdropGeometry, backdropMaterial);
  backdrop.position.z = -2.5;
  root.add(backdrop);

  // ============================================================================
  // BRUSHED METAL TILE MATERIAL (shared across all tiles)
  // ============================================================================
  const createTileMaterial = () => {
    const mat = new MeshStandardNodeMaterial();
    const matUV = uv();

    const gradTopVec = vec3(26 / 255, 26 / 255, 34 / 255);
    const gradBotVec = vec3(18 / 255, 18 / 255, 24 / 255);
    mat.colorNode = mix(gradTopVec, gradBotVec, matUV.y);

    mat.metalness = uniform(0.5);
    mat.roughness = uniform(0.55);
    mat.anisotropyIntensity = uniform(0.6);
    mat.anisotropyRotation = uniform(0);
    mat.clearcoat = uniform(0.2);
    mat.clearcoatRoughness = uniform(0.3);
    mat.emissiveIntensity = 0;

    return mat;
  };

  // ============================================================================
  // GRID CONTAINER (centered at origin)
  // ============================================================================
  const gridContainer = new Group();
  gridContainer.position.set(-TOTAL_GRID_WIDTH / 2, -TOTAL_GRID_HEIGHT / 2, 0);
  root.add(gridContainer);

  // ============================================================================
  // BUILD TILES
  // ============================================================================
  const tiles = [];
  const tileObjects = [];

  for (let row = 0; row < GRID_ROWS; row++) {
    for (let col = 0; col < GRID_COLS; col++) {
      const tileIndex = row * GRID_COLS + col;
      const brandMark = brandMarks[tileIndex] || '';

      const tileX = col * (TILE_WIDTH + GRID_GAP) + TILE_WIDTH / 2;
      const tileY = row * (TILE_HEIGHT + GRID_GAP) + TILE_HEIGHT / 2;

      const geometry = new PlaneGeometry(TILE_WIDTH, TILE_HEIGHT, 4, 4);
      const material = createTileMaterial();
      const tile = new Mesh(geometry, material);
      tile.position.set(tileX, tileY, 0);
      gridContainer.add(tile);

      tiles.push({
        mesh: tile,
        brandMark,
        material,
      });
      tileObjects.push(tile);
    }
  }

  // ============================================================================
  // RENDER BRAND MARKS AS TEXT
  // ============================================================================
  const textGroup = new Group();
  gridContainer.add(textGroup);

  for (let i = 0; i < tiles.length; i++) {
    const tile = tiles[i];
    const row = Math.floor(i / GRID_COLS);
    const col = i % GRID_COLS;

    const tileX = col * (TILE_WIDTH + GRID_GAP) + TILE_WIDTH / 2;
    const tileY = row * (TILE_HEIGHT + GRID_GAP) + TILE_HEIGHT / 2;

    const textMesh = ctx.fontAtlas.createText(tile.brandMark, {
      fontSize: 13,
      color: colorPaper,
      align: 'center',
      letterSpacingPx: 1.04,
    });

    textMesh.position.set(tileX, tileY, 0.01);
    textMesh.userData.opacity = 0.78;

    if (textMesh.children && textMesh.children.length > 0) {
      textMesh.children.forEach((child) => {
        if (child.material) {
          child.material.opacity = 0.78;
          child.material.transparent = true;
        }
      });
    }

    textGroup.add(textMesh);
    tile.textMesh = textMesh;
  }

  // ============================================================================
  // KICKER TEXT ("AS FEATURED IN")
  // ============================================================================
  const kickerMesh = ctx.fontAtlas.createText('AS FEATURED IN', {
    fontSize: 9,
    color: colorPaper,
    align: 'center',
    letterSpacingPx: 1.08,
  });
  kickerMesh.position.set(0, TOTAL_GRID_HEIGHT / 2 + KICKER_OFFSET_Y, 0);
  if (kickerMesh.children && kickerMesh.children.length > 0) {
    kickerMesh.children.forEach((child) => {
      if (child.material) {
        child.material.opacity = 0.78;
        child.material.transparent = true;
      }
    });
  }
  root.add(kickerMesh);

  // ============================================================================
  // ADD LIGHTING (key light rakes at 35° elevation for anisotropic sweep)
  // ============================================================================
  const { DirectionalLight } = ctx.THREE;

  const keyLight = new DirectionalLight(0xffffff, 1.2);
  const keyElevation = (35 * Math.PI) / 180;
  keyLight.position.set(
    5 * Math.cos(keyElevation),
    5 * Math.sin(keyElevation),
    0
  );
  keyLight.target.position.set(0, 0, 0);
  root.add(keyLight);
  root.add(keyLight.target);

  const rimLight = new DirectionalLight(0xffffff, 0.6);
  rimLight.position.set(-3, 1.5, 2);
  rimLight.target.position.set(0, 0, 0);
  root.add(rimLight);
  root.add(rimLight.target);

  // ============================================================================
  // ENTRANCE ANIMATION (stagger-cards: fade-up + translate-y)
  // ============================================================================
  const entranceTl = gsap.timeline({ paused: false });

  tileObjects.forEach((tile, idx) => {
    tile.position.y += 0.2;

    entranceTl.to(
      tile.position,
      {
        y: `-=0.2`,
        duration: 0.5,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
      },
      idx * 0.08
    );

    const textMesh = tiles[idx].textMesh;
    if (textMesh && textMesh.children) {
      entranceTl.to(
        textMesh.userData,
        {
          opacity: 0.78,
          duration: 0.5,
          ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
          onUpdate() {
            if (textMesh.children && textMesh.children.length > 0) {
              textMesh.children.forEach((child) => {
                if (child.material) {
                  child.material.opacity = textMesh.userData.opacity;
                }
              });
            }
          },
        },
        idx * 0.08
      );
    }
  });

  kickerMesh.position.y += 0.2;
  entranceTl.to(
    kickerMesh.position,
    {
      y: `-=0.2`,
      duration: 0.5,
      ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
    },
    0
  );

  entranceTl.to(
    kickerMesh.userData,
    {
      opacity: 1,
      duration: 0.5,
      ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
      onUpdate() {
        if (kickerMesh.children && kickerMesh.children.length > 0) {
          kickerMesh.children.forEach((child) => {
            if (child.material) {
              child.material.opacity = kickerMesh.userData.opacity;
            }
          });
        }
      },
    },
    0
  );

  // ============================================================================
  // HOVER INTERACTIONS (per-tile wordmark opacity + translateZ)
  // ============================================================================
  const hoverHandlers = {};

  tileObjects.forEach((tile, idx) => {
    const tileData = tiles[idx];

    hoverHandlers[`tile-${idx}-enter`] = () => {
      const textMesh = tileData.textMesh;
      if (!textMesh) return;

      gsap.to(textMesh.userData, {
        opacity: 1.0,
        duration: 0.16,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
        onUpdate() {
          if (textMesh.children && textMesh.children.length > 0) {
            textMesh.children.forEach((child) => {
              if (child.material) {
                child.material.opacity = textMesh.userData.opacity;
              }
            });
          }
        },
      });

      gsap.to(tile.position, {
        z: 0.05,
        duration: 0.16,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
      });
    };

    hoverHandlers[`tile-${idx}-exit`] = () => {
      const textMesh = tileData.textMesh;
      if (!textMesh) return;

      gsap.to(textMesh.userData, {
        opacity: 0.78,
        duration: 0.16,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
        onUpdate() {
          if (textMesh.children && textMesh.children.length > 0) {
            textMesh.children.forEach((child) => {
              if (child.material) {
                child.material.opacity = textMesh.userData.opacity;
              }
            });
          }
        },
      });

      gsap.to(tile.position, {
        z: 0,
        duration: 0.16,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
      });
    };

    tile.userData.tileIndex = idx;
  });

  // ============================================================================
  // CLEANUP
  // ============================================================================
  root.userData.cleanup = () => {
    entranceTl.kill();
    gsap.globalTimeline.getChildren().forEach((tl) => {
      if (tl._targets && tl._targets.some((t) => tileObjects.includes(t))) {
        tl.kill();
      }
    });

    backdrop.geometry.dispose();
    backdrop.material.dispose();

    tileObjects.forEach((tile) => {
      tile.geometry.dispose();
      tile.material.dispose();
    });

    textGroup.traverse((child) => {
      if (child.geometry) child.geometry.dispose();
      if (child.material) child.material.dispose();
    });

    kickerMesh.traverse((child) => {
      if (child.geometry) child.geometry.dispose();
      if (child.material) child.material.dispose();
    });

    keyLight.dispose();
    rimLight.dispose();
  };

  // ============================================================================
  // ATTACH EVENT HANDLERS
  // ============================================================================
  root.userData.handlers = hoverHandlers;

  return root;
}
